/**
 * Headline D3c verification: every config key the compiler emits traces back
 * to an intake field through the real D2 field map (generated by
 * tools/intake/generate.py from the 8-sheet template). The guard fails on
 * orphan keys — config keys that appeared without an intake source — and on
 * projection rows claiming field-map keys that no longer exist.
 */
import { describe, expect, it } from 'vitest'
import { TraceabilityError, assertTraceable, collectLeafPaths, compileWorkflowConfig } from './compiler.js'
import { FieldMap } from './fieldmap.js'
import { PROJECTIONS } from './mapping.js'
import { loadFieldMap, loadFieldMapCsvText, loadReferenceIntake } from './testutil.js'

const fieldMap = loadFieldMap()
const reference = loadReferenceIntake()

describe('config-key traceability (spec D3c acceptance)', () => {
  it('compiles the reference intake with every emitted key traced to an intake field', () => {
    const compiled = compileWorkflowConfig(reference, fieldMap, { customer: 'reference-medspa', version: 1 })
    // compileWorkflowConfig runs assertTraceable internally — reaching here
    // means zero orphans. Pin the exact reserved set so envelope drift fails
    // this test instead of silently growing:
    const traced = new Set(compiled.provenance.map((row) => row.path))
    const isCovered = (path: string): boolean =>
      traced.has(path) || (path.lastIndexOf('[') > 0 && isCovered(path.slice(0, path.lastIndexOf('['))))
    const reserved = collectLeafPaths(compiled.config)
      .filter((path) => !isCovered(path))
      .sort()
    expect(reserved).toEqual(
      [
        'ads.platforms[0]',
        'ads.platforms[1]',
        'approval.gate_actions[0]',
        'approval.gate_actions[1]',
        'approval.gate_actions[2]',
        'approval.gate_actions[3]',
        'approval.gate_actions[4]',
        'approval.gate_actions[5]',
        'approval.gate_actions[6]',
        'customer',
        'version',
        'workflow.lead_scoring.model',
        'workflow.lead_scoring.tiers.A',
        'workflow.lead_scoring.tiers.B',
        'workflow.lead_scoring.tiers.C',
        'workflow.purchase_signals.engine.fallback',
        'workflow.purchase_signals.engine.primary',
      ].sort(),
    )
    expect(compiled.provenance.length).toBeGreaterThan(60)
  })

  it('fails on orphan config keys — a key with no intake source cannot ship', () => {
    expect(() =>
      assertTraceable(
        { workflow: { rogue_key: 'appeared from nowhere' } },
        [],
        fieldMap,
      ),
    ).toThrow(TraceabilityError)
    try {
      assertTraceable({ workflow: { rogue_key: 'appeared from nowhere' } }, [], fieldMap)
      expect.unreachable('orphan keys must fail compilation')
    } catch (error) {
      expect((error as TraceabilityError).message).toContain('workflow.rogue_key')
    }
  })

  it('fails on orphan provenance — projections claiming field-map keys that do not exist', () => {
    // Tamper the field map: every knowledge_base reference becomes kb.company,
    // simulating template drift. The projection table must stop compiling.
    const csv = loadFieldMapCsvText().replaceAll('knowledge_base', 'kb.company')
    const drifted = FieldMap.fromCsv(csv)
    expect(() =>
      compileWorkflowConfig(reference, drifted, { customer: 'reference-medspa', version: 1 }),
    ).toThrow(/orphan provenance/)
  })

  it('every projection row references a config key that exists in the live field map', () => {
    const untraced = PROJECTIONS.filter((projection) => !fieldMap.configKeys.has(projection.tracesTo))
    expect(untraced.map((p) => `${p.intakeKey} → ${p.tracesTo}`)).toEqual([])
  })
})
